// scripts/cat2_verbs.cjs
// 300 Curated Hard & Everyday Questions on Dependent Prepositions (Verbs)
// IDs 251 - 550

function makeQ(id, question, correct, distractors, explanation) {
  const targetPos = id % 4;
  const filtered = distractors.filter(d => d.toLowerCase() !== correct.toLowerCase()).slice(0, 3);
  while (filtered.length < 3) {
    const pool = ["in", "on", "at", "by", "for", "with", "to", "from", "of", "about", "towards", "against"];
    for (const p of pool) {
      if (p.toLowerCase() !== correct.toLowerCase() && !filtered.includes(p)) {
        filtered.push(p);
        if (filtered.length === 3) break;
      }
    }
  }
  filtered.splice(targetPos, 0, correct);
  return {
    id,
    question,
    options: filtered,
    correctIndex: targetPos,
    explanation,
    category: "Dependent Prepositions (Verbs)"
  };
}

